head.script:
// https://inswave01.atlassian.net/browse/WAEA-1432
// 담당 범위 : dateValidCheck=true 일때의 검사 기준 (ioFormat / calendarValueType 포맷과 길이, 날짜/시간 범위, ioFormat 위치 기준)
//  - 활성화 여부(true / false / 미설정, dateValidSet 연동)와 실패 시 처리(invalidMessageFunc, 기본 메시지, 포커스 유지)는 column_P_dateValidCheck_1.xml 담당
//  - 유효성 체크 실패 여부는 invalidMessageFunc 호출 줄로 확인 (함수 실행 자체는 _1 에서 검증)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외
//    (편집 입력이 가능한 Body Column 전용 속성이며 Header / SubTotal / Footer Column 은 입력 수단이 없어 설정 영역 con 옵션 미생성)



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > dateValidCheck]<br/>inputType='calendar' 인 Column 에서 입력값에 대한 날짜/시간 유효성 체크를 활성화합니다.",
    "validation" : [
        "true 설정 시, Column 의 ioFormat 또는 calendarValueType 속성의 포맷과 길이가 일치하지 않으면 유효성 체크에 실패합니다.",
        "true 설정 시, 연/월/일/시/분/초 중 유효하지 않은 범위의 날짜 또는 시간이 있으면 유효성 체크에 실패합니다.",
        "Column 의 ioFormat 포맷에서 'yyyy', 'MM', 'dd', 'HH', 'mm', 'SS' 위치를 기준으로 검사하므로 포맷 구성에 맞추어 값을 입력해야 합니다.",
    ]
}

// 편집 종료 결과 출력 지연 타이머
scwin.editEndTimer = null;



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (calendarValueType=yearMonthDate, ioFormat=yyyyMMdd)
    con_calendarValueType.setValue("yearMonthDate");
    con_ioFormat.setValue("yyyyMMdd");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - cal : 검증 대상 Body Column (inputType="calendar" + dataType="date", dateValidCheck="true",
//          invalidMessageFunc="scwin.target1_cal_invalidMessageFunc" 고정)
//          calendarValueType / ioFormat 은 con (미설정이면 속성 자체를 넣지 않음)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] cal Column 은 dateValidCheck=true 고정, 유효성 체크에 실패하면 invalidMessageFunc 호출 줄 출력\n[절차] 결과창 clear -> cal 셀 클릭 -> 기존 값을 지우고 숫자 입력 -> 셀 밖(조건 영역) 클릭\n[입력 예] 길이 : 2026102 (yearMonthDate), 20261020 (yearMonthDateTime) / 범위 : 20261345, 20261131, 202610202530, 202610201060\n위치 : 15102026 과 20261015 를 ioFormat yyyyMMdd / ddMMyyyy 에서 비교\n편집이 유지되면 Esc 로 편집을 취소한 뒤 Target 재생성"', '', 'label1');

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cal" name="cal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // con 값 (미설정이면 속성 자체를 넣지 않는다)
    let properties = {
        calendarValueType : con_calendarValueType.getValue(),
        ioFormat : con_ioFormat.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oneditend"]);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:90px;" ' + eList + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column1" value="cal"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="260" style="" id="cal" inputType="calendar" dataType="date" viewType="icon" dateValidCheck="true"'
        + ' invalidMessageFunc="scwin.target1_cal_invalidMessageFunc" ' + cList + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 적용된 ioFormat 형식으로 초기값(2026-10-01 09:30:00) 설정
    let ioFormat = target1.getColumnOption("cal", "ioFormat");
    let initValue = ioFormat.replace("yyyy", "2026").replace("MM", "10").replace("dd", "01")
        .replace("HH", "09").replace("mm", "30").replace("SS", "00");
    dlt_bind.setJSON([
        { "cal" : initValue }
    ], false);

    // validation 1 ~ 3 : 적용된 calendarValueType / ioFormat 과 초기값
    wf_body_bottom.getObj("scwin").setReturnValue("calendarValueType : " + target1.getColumnOption("cal", "calendarValueType")
        + " / ioFormat : " + ioFormat
        + " -> 셀 표시값 : " + target1.getCellDisplayData(0, "cal")
        + " / DataList : '" + dlt_bind.getCellData(0, "cal") + "'");
}



// validation 1 ~ 3 : 유효성 체크 실패 시 실행되는 사용자 함수 (실패한 입력값 출력)
scwin.target1_cal_invalidMessageFunc = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("유효성 체크 실패 (invalidMessageFunc 호출) : 입력값 " + this.getCaller().getValue());
}



// validation 1 ~ 3 : 셀 밖 클릭으로 편집 종료를 시도한 뒤의 결과 (편집 유지 여부, 셀 표시값, DataList 값)
//  - 같은 클릭에서 여러 번 발생해도 마지막 상태 1줄만 출력
scwin.target1_oneditend = function (rowIndex, columnIndex, value) {
    clearTimeout(scwin.editEndTimer);
    scwin.editEndTimer = setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("입력값 " + value + " -> 편집 유지 : " + target1.isEditing()
            + " / 셀 표시값 : " + target1.getCellDisplayData(0, "cal")
            + " / DataList : '" + dlt_bind.getCellData(0, "cal") + "'");
    }, 300);
}
